%% 连续系统LQR控制策略对比分析
clear; clc; close all;

% 系统参数
A = 0.5;    % 系统矩阵
B = 1;      % 控制矩阵
x0 = 10;    % 初始状态
T = 8;      % 仿真时间（秒）
Q = 1;      % 状态代价权重
R = 1;      % 控制代价权重

% 时间向量
dt = 0.01;  % 时间步长
t = 0:dt:T; % 时间点
N = length(t);  % 时间点数量

%% 1. 计算连续时间LQR最优增益
% 求解连续时间代数Riccati方程 (CARE)
P = care(A, B, Q, R);  % 求解Riccati方程
K_opt = R\B'*P;        % 最优反馈增益 K_opt ≈1.6180

% 策略定义
K_strong = 2;  % 较强反馈增益   由于是一阶连续系统，怎么大都不会出现超调
K_con = 1.3;     % 保守反馈增益

fprintf('=== 连续系统控制策略分析 ===\n'); %[output:5b29a90d]
fprintf('LQR最优增益: K_opt = %.4f\n', K_opt); %[output:1772993e]
fprintf('较强反馈增益: K_strong = %.4f\n', K_strong); %[output:6dc37702]
fprintf('保守控制增益: K_con = %.4f\n\n', K_con); %[output:278930a9]

%% 2. 策略1: LQR最优控制
% 闭环系统矩阵
A_cl_opt = A - B*K_opt;

% 求解状态方程
x_opt = zeros(1, N);
u_opt = zeros(1, N);
J_opt_single = zeros(1, N);
J_opt_cum = zeros(1, N);

x_opt(1) = x0;
u_opt(1) = -K_opt * x_opt(1);
J_opt_single(1) = (x_opt(1)^2 + u_opt(1)^2) * dt;
J_opt_cum(1) = J_opt_single(1);

% 数值积分求解
for k = 2:N
    % 使用欧拉法（也可用ode45，但这里为简单用欧拉法）
    x_opt(k) = x_opt(k-1) + (A_cl_opt * x_opt(k-1)) * dt;
    u_opt(k) = -K_opt * x_opt(k);
    J_opt_single(k) = (x_opt(k)^2 + u_opt(k)^2) * dt;
    J_opt_cum(k) = J_opt_cum(k-1) + J_opt_single(k);
end

% 解析解（用于验证）
% 连续系统解析解: x(t) = x0 * exp((A-B*K_opt)*t)
t_analytic = linspace(0, T, 1000);
x_opt_analytic = x0 * exp((A - B*K_opt) * t_analytic);
u_opt_analytic = -K_opt * x_opt_analytic;

%% 3. 策略2: 较强反馈控制
A_cl_strong = A - B*K_strong;

x_strong = zeros(1, N);
u_strong = zeros(1, N);
J_strong_single = zeros(1, N);
J_strong_cum = zeros(1, N);

x_strong(1) = x0;
u_strong(1) = -K_strong * x_strong(1);
J_strong_single(1) = (x_strong(1)^2 + u_strong(1)^2) * dt;
J_strong_cum(1) = J_strong_single(1);

for k = 2:N
    x_strong(k) = x_strong(k-1) + (A_cl_strong * x_strong(k-1)) * dt;
    u_strong(k) = -K_strong * x_strong(k);
    J_strong_single(k) = (x_strong(k)^2 + u_strong(k)^2) * dt;
    J_strong_cum(k) = J_strong_cum(k-1) + J_strong_single(k);
end

%% 4. 策略3: 保守控制
A_cl_con = A - B*K_con;

x_con = zeros(1, N);
u_con = zeros(1, N);
J_con_single = zeros(1, N);
J_con_cum = zeros(1, N);

x_con(1) = x0;
u_con(1) = -K_con * x_con(1);
J_con_single(1) = (x_con(1)^2 + u_con(1)^2) * dt;
J_con_cum(1) = J_con_single(1);

for k = 2:N
    x_con(k) = x_con(k-1) + (A_cl_con * x_con(k-1)) * dt;
    u_con(k) = -K_con * x_con(k);
    J_con_single(k) = (x_con(k)^2 + u_con(k)^2) * dt;
    J_con_cum(k) = J_con_cum(k-1) + J_con_single(k);
end

%% 5. 计算开环系统响应（无控制）
% 开环系统: dx/dt = A*x, 无控制输入
x_open = x0 * exp(A * t);  % 解析解
J_open_single = x_open.^2 * dt;
J_open_cum = cumsum(J_open_single);

%% 6. 计算最终总代价（无穷时间代价的有限时间近似）
total_cost_opt = J_opt_cum(end);
total_cost_strong = J_strong_cum(end);
total_cost_con = J_con_cum(end);
total_cost_open = J_open_cum(end);

%% 7. 绘制控制输入u随时间变化，z轴为累计代价
figure('Color', 'w', 'Position', [100, 100, 1200, 900]); %[output:12573e38]

% 创建三维坐标系
ax1 = subplot(2,2,[1,3]); %[output:12573e38]
hold on; grid on; box on; %[output:12573e38]
view(45, 30); %[output:12573e38]

% 由于连续系统数据点太多，我们抽样绘制以减少绘图负担
skip = 20;  % 每隔20个点绘制一个
t_sampled = t(1:skip:end);
u_opt_sampled = u_opt(1:skip:end);
u_strong_sampled = u_strong(1:skip:end);
u_con_sampled = u_con(1:skip:end);
J_opt_cum_sampled = J_opt_cum(1:skip:end);
J_strong_cum_sampled = J_strong_cum(1:skip:end);
J_con_cum_sampled = J_con_cum(1:skip:end);

% 绘制三条控制输入轨迹
% 策略1: LQR最优 (蓝色)
plot3(t_sampled, u_opt_sampled, J_opt_cum_sampled, '-', 'Color', [0, 0.4470, 0.7410], ... %[output:12573e38]
    'LineWidth', 2, 'DisplayName', sprintf('策略1: LQR最优 (K=%.3f, J=%.2f)', K_opt, total_cost_opt)); %[output:12573e38]

% 策略2: 较强反馈 (红色)
plot3(t_sampled, u_strong_sampled, J_strong_cum_sampled, '-', 'Color', [0.8500, 0.3250, 0.0980], ... %[output:12573e38]
    'LineWidth', 2, 'DisplayName', sprintf('策略2: 较强反馈 (K=%.3f, J=%.2f)', K_strong, total_cost_strong)); %[output:12573e38]

% 策略3: 保守控制 (绿色)
plot3(t_sampled, u_con_sampled, J_con_cum_sampled, '-', 'Color', [0.4660, 0.6740, 0.1880], ... %[output:12573e38]
    'LineWidth', 2, 'DisplayName', sprintf('策略3: 保守控制 (K=%.3f, J=%.2f)', K_con, total_cost_con)); %[output:12573e38]

% 在关键时间点添加标记
key_times = [0, 1, 2, 4, 8];
for kt = 1:length(key_times)
    [~, idx] = min(abs(t - key_times(kt)));
    if idx <= length(t)
        % 策略1标记
        plot3(t(idx), u_opt(idx), J_opt_cum(idx), 'o', ... %[output:12573e38]
            'MarkerFaceColor', [0, 0.4470, 0.7410], 'MarkerEdgeColor', 'k', 'MarkerSize', 8); %[output:12573e38]
        text(t(idx), u_opt(idx), J_opt_cum(idx)+5, ...
            sprintf('t=%.1f\nu=%.2f', t(idx), u_opt(idx)), ...
            'FontSize', 8, 'HorizontalAlignment', 'center', 'Color', [0, 0.4470, 0.7410]);
        
        % 策略2标记
        plot3(t(idx), u_strong(idx), J_strong_cum(idx), 's', ...
            'MarkerFaceColor', [0.8500, 0.3250, 0.0980], 'MarkerEdgeColor', 'k', 'MarkerSize', 8);
        
        % 策略3标记
        plot3(t(idx), u_con(idx), J_con_cum(idx), '^', ...
            'MarkerFaceColor', [0.4660, 0.6740, 0.1880], 'MarkerEdgeColor', 'k', 'MarkerSize', 8);
    end
end

% 绘制零输入线
plot3([0, T], [0, 0], [0, 0], 'k--', 'LineWidth', 1.5, ... %[output:12573e38]
    'DisplayName', '零输入线 (u=0)'); %[output:12573e38]

% 添加坐标轴标签
xlabel('时间 t (秒)', 'FontSize', 12, 'FontWeight', 'bold'); %[output:12573e38]
ylabel('控制输入 u(t)', 'FontSize', 12, 'FontWeight', 'bold'); %[output:12573e38]
zlabel('累计代价 J_{cum}(t) = ∫_0^t (x(τ)^2+u(τ)^2)dτ', 'FontSize', 12, 'FontWeight', 'bold'); %[output:12573e38]
title('控制输入u随时间变化，z轴为累计代价', 'FontSize', 14, 'FontWeight', 'bold'); %[output:12573e38]
legend('Location', 'best', 'FontSize', 10); %[output:12573e38]
grid on; %[output:12573e38]

% 设置坐标轴范围
xlim([0, T]); %[output:12573e38]
u_max = max([abs(u_opt), abs(u_strong), abs(u_con)]);
ylim([-u_max*1.1, u_max*1.1]); %[output:12573e38]
zlim([0, max([J_opt_cum, J_strong_cum, J_con_cum])*1.1]); %[output:12573e38]

%% 8. 图2: 状态x随时间变化，z轴为累计代价
ax2 = subplot(2,2,[2,4]); %[output:12573e38]
hold on; grid on; box on; %[output:12573e38]
view(45, 30); %[output:12573e38]

% 抽样数据
x_opt_sampled = x_opt(1:skip:end);
x_strong_sampled = x_strong(1:skip:end);
x_con_sampled = x_con(1:skip:end);

% 绘制三条状态轨迹
% 策略1: LQR最优 (蓝色)
plot3(t_sampled, x_opt_sampled, J_opt_cum_sampled, '-', 'Color', [0, 0.4470, 0.7410], ... %[output:12573e38]
    'LineWidth', 2, 'DisplayName', sprintf('策略1: LQR最优 (K=%.3f, J=%.2f)', K_opt, total_cost_opt)); %[output:12573e38]

% 策略2: 较强反馈 (红色)
plot3(t_sampled, x_strong_sampled, J_strong_cum_sampled, '-', 'Color', [0.8500, 0.3250, 0.0980], ... %[output:12573e38]
    'LineWidth', 2, 'DisplayName', sprintf('策略2: 较强反馈 (K=%.3f, J=%.2f)', K_strong, total_cost_strong)); %[output:12573e38]

% 策略3: 保守控制 (绿色)
plot3(t_sampled, x_con_sampled, J_con_cum_sampled, '-', 'Color', [0.4660, 0.6740, 0.1880], ... %[output:12573e38]
    'LineWidth', 2, 'DisplayName', sprintf('策略3: 保守控制 (K=%.3f, J=%.2f)', K_con, total_cost_con)); %[output:12573e38]

% 在关键时间点添加标记
for kt = 1:length(key_times)
    [~, idx] = min(abs(t - key_times(kt)));
    if idx <= length(t)
        % 策略1标记
        plot3(t(idx), x_opt(idx), J_opt_cum(idx), 'o', ... %[output:12573e38]
            'MarkerFaceColor', [0, 0.4470, 0.7410], 'MarkerEdgeColor', 'k', 'MarkerSize', 8); %[output:12573e38]
        text(t(idx), x_opt(idx), J_opt_cum(idx)+5, ...
            sprintf('t=%.1f\nx=%.2f', t(idx), x_opt(idx)), ...
            'FontSize', 8, 'HorizontalAlignment', 'center', 'Color', [0, 0.4470, 0.7410]);
        
        % 策略2标记
        plot3(t(idx), x_strong(idx), J_strong_cum(idx), 's', ...
            'MarkerFaceColor', [0.8500, 0.3250, 0.0980], 'MarkerEdgeColor', 'k', 'MarkerSize', 8);
        
        % 策略3标记
        plot3(t(idx), x_con(idx), J_con_cum(idx), '^', ...
            'MarkerFaceColor', [0.4660, 0.6740, 0.1880], 'MarkerEdgeColor', 'k', 'MarkerSize', 8);
    end
end

