%% 补充：值函数曲面绘制
fprintf('\n=== 绘制值函数曲面 ===\n'); %[output:437f55c7]

% 为绘制曲面，我们需要创建一个状态网格和控制输入网格
x_range = linspace(-10, 10, 50);  % 状态范围
u_range = linspace(-20, 20, 50);  % 控制输入范围
t_range = linspace(0, T, 50);     % 时间范围

% 创建网格
[X, T_mesh] = meshgrid(x_range, t_range);
[U, T_mesh2] = meshgrid(u_range, t_range);

%% 计算值函数曲面 Jcum(x,t)
% 对于每个时间t和状态x，计算从0到t的累计代价
% 由于是线性系统，我们可以解析计算值函数
% 值函数 V(x,t) = x' * P(t) * x，其中P(t)满足Riccati微分方程
% 但这里我们要求的是从0时刻开始的累计代价，而不是从t到T的代价
% 我们可以通过仿真计算：从状态x0开始，在最优控制下，到时间t的累计代价

% 初始化值函数曲面矩阵
Jcum_xt = zeros(length(t_range), length(x_range));

% 对每个初始状态进行仿真
for i = 1:length(x_range)
    x0_i = x_range(i);
    
    % 使用最优控制策略仿真
    x_opt_i = zeros(1, N);
    u_opt_i = zeros(1, N);
    J_opt_cum_i = zeros(1, N);
    
    x_opt_i(1) = x0_i;
    u_opt_i(1) = -K_opt * x_opt_i(1);
    J_opt_cum_i(1) = (x_opt_i(1)^2 + u_opt_i(1)^2) * dt;
    
    for k = 2:N
        x_opt_i(k) = x_opt_i(k-1) + (A_cl_opt * x_opt_i(k-1)) * dt;
        u_opt_i(k) = -K_opt * x_opt_i(k);
        J_opt_single_k = (x_opt_i(k)^2 + u_opt_i(k)^2) * dt;
        J_opt_cum_i(k) = J_opt_cum_i(k-1) + J_opt_single_k;
    end
    
    % 将累计代价插值到时间网格上
    for j = 1:length(t_range)
        [~, idx] = min(abs(t - t_range(j)));
        Jcum_xt(j, i) = J_opt_cum_i(idx);
    end
end

%% 计算值函数曲面 Jcum(u,t)
% 对于控制输入u，我们需要找到对应的状态x
% 在最优控制下，u = -K_opt * x，所以 x = -u/K_opt
% 然后计算从该状态开始的累计代价

Jcum_ut = zeros(length(t_range), length(u_range));

for i = 1:length(u_range)
    u_i = u_range(i);
    
    % 计算对应的初始状态
    x0_i = -u_i / K_opt;
    
    % 如果K_opt接近0，需要特殊处理
    if abs(K_opt) < 1e-6
        x0_i = 0;  % 避免除以0
    end
    
    % 使用最优控制策略仿真
    x_opt_i = zeros(1, N);
    u_opt_i = zeros(1, N);
    J_opt_cum_i = zeros(1, N);
    
    x_opt_i(1) = x0_i;
    u_opt_i(1) = -K_opt * x_opt_i(1);
    J_opt_cum_i(1) = (x_opt_i(1)^2 + u_opt_i(1)^2) * dt;
    
    for k = 2:N
        x_opt_i(k) = x_opt_i(k-1) + (A_cl_opt * x_opt_i(k-1)) * dt;
        u_opt_i(k) = -K_opt * x_opt_i(k);
        J_opt_single_k = (x_opt_i(k)^2 + u_opt_i(k)^2) * dt;
        J_opt_cum_i(k) = J_opt_cum_i(k-1) + J_opt_single_k;
    end
    
    % 将累计代价插值到时间网格上
    for j = 1:length(t_range)
        [~, idx] = min(abs(t - t_range(j)));
        Jcum_ut(j, i) = J_opt_cum_i(idx);
    end
end

