view(45, 30); %[output:5499fcb5]

% 绘制三条重要的轨迹：

% 1. 固定初始状态x0=10的轨迹（黄色虚线）
% 这条轨迹是：从x0=10开始，在最优控制下，状态如何随时间变化
% 在曲面上，这应该是沿着(x(t), t, Jcum(10, t))的轨迹
plot3(x_opt(1:skip:end), t(1:skip:end), J_opt_cum(1:skip:end), ... %[output:5499fcb5]
    'y--', 'LineWidth', 3, 'DisplayName', '实际状态轨迹 (x(t))'); %[output:5499fcb5]

% 2. 固定初始状态x0=10在曲面上的投影（蓝色实线）
% 这条轨迹是：假设初始状态为x0=10，在最优控制下，累计代价如何随时间变化
% 在曲面上，这应该是沿着(10, t, Jcum(10, t))的直线
% 我们需要计算Jcum(10, t) - 这实际上就是J_opt_cum(t)
plot3(10*ones(size(t(1:skip:end))), t(1:skip:end), J_opt_cum(1:skip:end), ... %[output:5499fcb5]
    'b-', 'LineWidth', 2.5, 'DisplayName', '固定x0=10的代价轨迹'); %[output:5499fcb5]

% 3. 曲面的"山谷"线（红色实线）
% 对于每个时间t，找到使Jcum(x,t)最小的x
% 这应该是x=0，因为最优控制的目标是使系统状态归零
% 实际上，对于LQR问题，最优轨迹应该沿着Jcum(x,t)的最小值线
t_min_idx = 1:5:length(t_range);
x_min_line = zeros(size(t_min_idx));
Jcum_min_line = zeros(size(t_min_idx));

