%% 关键解释：为什么实际轨迹不沿着山谷？
fprintf('\n=== 为什么实际轨迹不沿着Jcum(x,t)曲面的山谷？ ===\n\n'); %[output:0ba61352]
fprintf('1. Jcum(x,t)曲面的定义：\n'); %[output:4469a534]
fprintf('   Jcum(x,t) 表示从0时刻开始，到时间t为止的累计代价。\n'); %[output:7cc01c87]
fprintf('   注意：这里的x是当前状态，但累计代价是从t=0开始计算的。\n\n'); %[output:33e78e04]

fprintf('2. 曲面的"山谷"线：\n'); %[output:0bbd20d5]
fprintf('   "山谷"线对应每个时间t下，使Jcum(x,t)最小的状态x。\n'); %[output:8706ee24]
fprintf('   对于LQR问题，理想情况下，山谷线应该是x=0，因为：\n'); %[output:419d6470]
fprintf('   - 在t=0时刻，最小Jcum的状态是x=0（没有初始误差）\n'); %[output:20d638e6]
fprintf('   - 在t>0时刻，如果系统一直保持在x=0，累计代价最小\n\n'); %[output:68bb36d5]

fprintf('3. 实际轨迹：\n'); %[output:4abacf38]
fprintf('   实际系统从初始状态x0=10开始，在最优控制下收敛到0。\n'); %[output:6ce702c0]
fprintf('   轨迹是：x(t) = 10 * exp((A-B*K_opt)*t)\n'); %[output:78cf1f46]
fprintf('   这不是山谷线（x=0），因为系统需要时间从x0=10收敛到0。\n\n'); %[output:5eeda75f]

fprintf('4. 为什么实际轨迹不在山谷线上？\n'); %[output:022f08bc]
fprintf('   - 山谷线x=0是理想情况：如果系统始终在平衡点，代价最小\n'); %[output:22a69f31]
fprintf('   - 但实际系统有初始状态x0=10，必须从这个状态出发\n'); %[output:60b8e5df]
fprintf('   - 从非零初始状态到平衡点需要时间和控制能量\n'); %[output:1c48a35c]
fprintf('   - 因此，实际轨迹不可能从一开始就沿着山谷线\n\n'); %[output:8e1d442e]

fprintf('5. 数学解释：\n'); %[output:23b11ca1]
fprintf('   对于连续时间LQR，值函数V(x,t)满足HJB方程。\n'); %[output:4c744ca6]
fprintf('   最优轨迹是使哈密顿量最小化的轨迹，而不是使瞬时状态最小的轨迹。\n'); %[output:80cdb02d]
fprintf('   最优轨迹需要在快速收敛（使用更多控制能量）和节省控制能量之间权衡。\n\n'); %[output:5cfa4204]

%% 验证：绘制Jcum(x,t)在固定时间的切片
figure('Color', 'w', 'Position', [200, 200, 1200, 400]); %[output:1891daab]

% 选择几个关键时间点
time_points = [0, 1, 2, 4, 8];
colors = {'b', 'r', 'g', 'm', 'k'};
line_styles = {'-', '--', ':', '-.', '-'};

for i = 1:length(time_points)
    subplot(1, length(time_points), i); %[output:1891daab]
    hold on; grid on; box on;
    
    % 找到最接近的时间索引
    [~, t_idx] = min(abs(t_range - time_points(i)));
    
    % 绘制Jcum(x)在固定时间的切片
    plot(x_range, Jcum_xt(t_idx, :), [colors{i} line_styles{i}], ...
        'LineWidth', 2, 'DisplayName', sprintf('t=%.1f', time_points(i)));
    
    % 标记实际轨迹在该时间的点
    [~, actual_t_idx] = min(abs(t - time_points(i)));
    x_actual = x_opt(actual_t_idx);
    Jcum_actual = J_opt_cum(actual_t_idx);
    
    plot(x_actual, Jcum_actual, 'ko', 'MarkerFaceColor', 'y', ...
        'MarkerSize', 10, 'MarkerEdgeColor', 'k', ...
        'DisplayName', sprintf('实际点: x=%.2f', x_actual));
    
    % 标记最小值点
    [Jmin, min_idx] = min(Jcum_xt(t_idx, :));
    x_min = x_range(min_idx);
    
    plot(x_min, Jmin, 'r*', 'MarkerSize', 12, 'LineWidth', 2, ...
        'DisplayName', sprintf('最小值: x=%.2f', x_min));
    
    xlabel('系统状态 x', 'FontSize', 10, 'FontWeight', 'bold');
    ylabel(sprintf('J_{cum}(x, t=%.1f)', time_points(i)), ...
        'FontSize', 10, 'FontWeight', 'bold');
    title(sprintf('t=%.1f秒时的Jcum(x)切片', time_points(i)), ...
        'FontSize', 11, 'FontWeight', 'bold');
    legend('Location', 'best', 'FontSize', 8);
    
    % 添加文本说明
    text(x_actual, Jcum_actual, sprintf(' 实际\n x=%.2f\n J=%.1f', ...
        x_actual, Jcum_actual), 'FontSize', 8, 'VerticalAlignment', 'bottom');
    text(x_min, Jmin, sprintf(' 最小\n x=%.2f\n J=%.1f', ...
        x_min, Jmin), 'FontSize', 8, 'VerticalAlignment', 'bottom');
    
    xlim([min(x_range), max(x_range)]);
    ylim([0, max(Jcum_xt(t_idx, :))*1.1]);
end

sgtitle('Jcum(x,t)在不同时间点的切片', 'FontSize', 14, 'FontWeight', 'bold'); %[output:1891daab]

%% 最终总结
fprintf('=== 总结 ===\n'); %[output:502a70fa]
fprintf('1. Jcum(x,t)曲面的"山谷"线对应每个时间t下使累计代价最小的状态x。\n'); %[output:3d4527a8]
fprintf('2. 对于LQR问题，山谷线是x=0，即系统始终保持在平衡点。\n'); %[output:6d40edb5]
fprintf('3. 实际轨迹从x0=10开始，需要时间收敛到0，因此不沿着山谷线。\n'); %[output:0e158d92]
fprintf('4. 实际轨迹是最优的，它在系统动力学约束下最小化总代价。\n'); %[output:92b8dd50]
fprintf('5. 山谷线是理想情况，实际轨迹是受到初始条件约束的最优解。\n\n'); %[output:20e73907]

fprintf('实际轨迹的数学表示：\n'); %[output:75b93834]
fprintf('   x*(t) = %.2f * exp(%.4f * t)\n', x0, A-B*K_opt); %[output:56975b65]
fprintf('   其中，A-B*K_opt = %.2f - %.2f*%.4f = %.4f\n', A, B, K_opt, A-B*K_opt); %[output:97319531]
fprintf('   收敛速率: %.4f\n', -(A-B*K_opt)); %[output:77e7b3ea]

% 计算最终时刻的实际位置与山谷线的距离
fprintf('\n在t=%.1f秒时：\n', T); %[output:53630acf]
fprintf('   实际状态: x(%.1f) = %.4f\n', T, x_opt(end)); %[output:604ee9fa]
fprintf('   山谷线状态: x_min = %.4f\n', 0); %[output:4564b6d4]
fprintf('   距离山谷线的偏差: %.4f\n', abs(x_opt(end) - 0)); %[output:8c1a6da3]
fprintf('   对应的代价增加: %.4f\n\n', J_opt_cum(end) - 0); %[output:8954c9fc]

